const body = $('Recall complete (Webhook)').first().json.body || {};
const d = body.data || {};
const meta = (d.bot && d.bot.metadata) || d.metadata || body.metadata || {};
let text = '';
const segs = Array.isArray($json) ? $json : ($json.transcript || []);
try { for (const s of segs) { const spk = s.speaker || (s.participant && s.participant.name) || 'Speaker'; const words = (s.words || []).map(w => w.text).join(' '); text += spk + ': ' + words + '\n'; } } catch (e) {}
if (!text) text = JSON.stringify($json);
const header = 'Known client: company=' + (meta.company||'') + ', contact=' + (meta.contactName||'') + ', email=' + (meta.contactEmail||'') + ', industry=' + (meta.industry||'') + '\n\n';
return [{ json: { transcript: header + text, source: 'recall', date: new Date().toISOString().slice(0,10) } }];

const f = $json;
const header = 'Known client: company=' + (f['Client company']||'') + ', contact=' + (f['Contact name']||'') + ', email=' + (f['Contact email']||'') + ', industry=' + (f['Industry']||'') + '\n\n';
return [{ json: { transcript: header + (f['Transcript or notes']||''), source: 'paste', date: new Date().toISOString().slice(0,10) } }];

const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';
const cleaned = raw.replace(/^```(json)?/i,'').replace(/```\s*$/,'').trim();
return [{ json: { discovery: JSON.parse(cleaned) } }];

const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';
const cleaned = raw.replace(/^```(json)?/i,'').replace(/```\s*$/,'').trim();
return [{ json: JSON.parse(cleaned) }];

const draft = $json;
const resumeUrl = $execution.resumeUrl;
const payload = JSON.stringify({ draft, resumeUrl });
const b64 = Buffer.from(payload, 'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
const link = 'https://s3-offer-editor-app.vercel.app/#' + b64;
return [{ json: { reviewLink: link, ownerEmail: 'ytiemani@zohomail.com', clientCompany: (draft.client && draft.client.company) || '' } }];

const body = $json.body || $json;
if (!body.approved) { throw new Error('Offer was not approved.'); }
return [{ json: { offer: body.offer, html: body.html || '' } }];
